<?php $test=str_contains((string)($_SERVER['SCRIPT_NAME']??''),'scoring-tests');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Draft Details</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:820px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3">Edit Draft Details</h1><p class="text-muted">Available only before any judge scoring is saved.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($round&&!$error):?><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$id?>"><input type="hidden" name="mode" value="<?=e($mode)?>"><div class="col-12"><label class="form-label">Event Name</label><input class="form-control" name="event_name" maxlength="190" value="<?=e($round['event_name'])?>" required></div><div class="col-md-6"><label class="form-label">Event Date</label><input class="form-control" type="date" name="event_date" value="<?=e((string)$round['event_date'])?>"></div><div class="col-md-6"><label class="form-label"><?=e(ucfirst((string)$round['round_type']))?> Date &amp; Time</label><input class="form-control" type="datetime-local" name="scheduled_at" value="<?=e(!empty($round['scheduled_at'])?date('Y-m-d\TH:i',strtotime((string)$round['scheduled_at'])):'')?>"><div class="form-text">Specific schedule for this round.</div></div><div class="col-md-6"><label class="form-label">Dance Style</label><select class="form-select" name="dance_style" id="draftDance"><option value="bachata" <?=($round['dance_style']??'bachata')==='bachata'?'selected':''?>>Bachata</option><option value="salsa" <?=($round['dance_style']??'bachata')==='salsa'?'selected':''?>>Salsa</option></select></div><div class="col-12"><label class="form-label">Division</label><select class="form-select" name="division" id="draftDivision"><?php foreach(['novice'=>'Novice','intermediate'=>'Intermediate','advanced'=>'Advanced','all_star'=>'All Star','bachata_rising'=>'Bachata Rising','bachata_open'=>'Bachata Open','bachata_invitational'=>'Bachata Invitational','salsa_rising'=>'Salsa Rising','salsa_open'=>'Salsa Open'] as $value=>$label):$only=str_starts_with($value,'salsa_')?'salsa':(str_starts_with($value,'bachata_')?'bachata':'');?><option value="<?=$value?>" data-dance="<?=$only?>" <?=$round['division']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary">Save Draft Details</button><a class="btn btn-outline-secondary" href="index.php?<?=$test?'legacy=1&test_mode='.e($mode):'mode='.e($mode)?>">Cancel</a></div></form><?php else:?><a class="btn btn-dark" href="index.php?<?=$test?'legacy=1&test_mode='.e($mode):'mode='.e($mode)?>">Back</a><?php endif;?></div></div></main><script>const d=document.getElementById('draftDance'),v=document.getElementById('draftDivision');if(d&&v){function sync(){[...v.options].forEach(o=>{o.hidden=!!o.dataset.dance&&o.dataset.dance!==d.value;o.disabled=o.hidden});if(v.selectedOptions[0]?.disabled)v.value='novice'}d.addEventListener('change',sync);sync()}</script></body></html>
